func getInitials(name string) string {
	if len(name) == 0 {
		return "?"
	}
	runes := []rune(name)
	if len(runes) == 1 {
		return string(runes[0:1])
	}
	// Find first two letters or first letter of first two words
	initials := ""
	words := 0
	for i, r := range runes {
		if i == 0 || (i > 0 && runes[i-1] == ' ') {
			initials += string(r)
			words++
			if words >= 2 {
				break
			}
		}
	}
	if initials == "" {
		return string(runes[0:1])
	}
	return initials
}

